"""Scope and reproduction notes for the restored frozen CL3 figures."""
import json
from pathlib import Path
import pandas as pd
from .paths import MOTIVATION


def write_notes(config):
    ranking=pd.read_csv(MOTIVATION/'ranking-panel.csv')
    errors=pd.read_csv(MOTIVATION/'rmse-panel.csv')
    decoding=pd.read_csv(config['decoding_statistics'])
    overall=pd.read_csv(config['overall_statistics'])
    contact=ranking[ranking.descriptor.eq('b_contact_invd2')].sort_values('group_index')
    error=errors[errors.descriptor.eq('b_contact_invd2')].sort_values('group_index')
    assert contact.n.sum()==733 and decoding.n.eq(732).all()
    labels=', '.join(contact.group);counts='/'.join(contact.n.astype(str))
    scope='Current figures use the original frozen filtered CL3 test: 733 affinity cases and the same 732 complete cases for all five decoding models. The additional 430 exploratory cases are excluded from every current panel. One alternate-location descriptor is missing; the shared eight-target complete-case rule accounts for the one-case decoding difference.'
    bins=f'Contact B factor uses {labels} Å², n={counts}; the finite middle range includes its lower bound and excludes its upper bound. The ≥30 tail includes all remaining high-B cases. These are exploratory user-requested absolute ranges, not universal uncertainty thresholds. Other continuous descriptors retain cohort-specific terciles; alternate locations use zero / lower-positive / higher-positive groups. Bin choices were explored previously; the intervals do not account for this selection.'
    if config['contact_b_binning']=='quartiles':
        cuts=', '.join(f'{v:.8f}' for v in contact.upper_bound.dropna())
        bins=f'Contact B factor uses empirical quartiles Q1–Q4, with counts {counts} and exact stored boundaries {cuts} Å². Equal values are kept together; each boundary belongs to the higher quartile. These are equal-count groups, not equal-width physical intervals. Other continuous descriptors retain cohort-specific terciles; alternate locations use zero / lower-positive / higher-positive groups. The cutoffs are fixed during bootstrap and the intervals do not account for earlier exploratory binning choices.'
    methods='Affinity uses the saved five-seed CPU probes with frozen manuscript CoE/CoDE embeddings: original CL123 train/validation/test = 1559/410/733, raw features and pK, scalar MSE head, hidden 128, dropout 0.1, Adam lr 0.001 and weight decay 0.0001, batch 64, maximum 200 epochs, validation-Spearman early stopping with patience 30. Original per-complex predictions are verified after restoring float32 precision; no heads are refit for this redraw. ΔSpearman and ΔRMSE average the five within-bin model differences. Intervals use 8000 paired-complex bootstrap resamples with fitted seeds and bin membership fixed; they are pointwise and do not resample protein families or training seeds.'
    decoding_scope='Decoding restores the original 732-case out-of-fold fits, rather than selecting 732 rows from the expanded-cohort decoders. All five models have identical case order, targets and outer folds, verified from saved OOF files. Ridge decoding uses five outer and three inner folds with training-fold scaling and inner-validation penalty selection. Bars show held-out Spearman correlation; this measures descriptor recoverability, not calibrated uncertainty or causal use for affinity. Folds split random complexes, not protein families.'
    model_scope='CoE and CoDE use the original cached 640-D ChannelViT features (CoE epoch 49, CDG v2 epoch 25). DeepDTA uses the existing CPU-refit validation-selected CNN checkpoint and 512-D hidden vectors. ProFSA restores the uploaded frozen 1024-D ligand/pocket CLS cache used in the original 732-case decoding. Nesso-1 uses the original public-v1.0.0 inference features, 384-D pooled final Pairformer blocks. Nesso-1† retains the manuscript affinity-pretraining leakage caveat. Exact feature sources and decoder protocols remain in the original representation and baseline folders.'
    historical='The historical manuscript/report CL123 CDG v2 row is Pearson 0.645, Spearman 0.621, RMSE 1.387. The 0.645 value is not Spearman. Its report builder points to the MSE-only probe CSV and labels that recipe as three-seed. The current uncertainty experiment is a separately saved five-seed CPU rerun: Spearman 0.620937, RMSE 1.405872. Thus the rank score agrees to three decimals, but the RMSE is not an exact reproduction; seed count and execution differ, and a specific cause has not been established without the historical per-case predictions. See the manuscript table and its probe CSV.'
    table=['| Contact B factor (Å²) | n | ΔSpearman [95% CI] | ΔRMSE [95% CI], pK |','|---|---:|---:|---:|']
    for a,b in zip(contact.itertuples(),error.itertuples()):
        table.append(f'| {a.group} | {a.n} | {a.estimate:+.3f} [{a.ci_lo:+.3f}, {a.ci_hi:+.3f}] | {b.estimate:+.3f} [{b.ci_lo:+.3f}, {b.ci_hi:+.3f}] |')
    model_table=['| Quartile | n | CoE Spearman | CoDE Spearman | Relative Spearman change |','|---|---:|---:|---:|---:|']
    if config.get('combined_affinity_display')=='models':
        for r in contact.itertuples():
            model_table.append(f'| {r.quartile} | {r.n} | {r.coe_spearman:.3f} | {r.code_spearman:.3f} | {r.relative_spearman_change_pct:+.1f}% |')
    display_table=model_table if config.get('combined_affinity_display')=='models' else table
    full=['| CPU five-seed mean, n=733 | Pearson | Spearman | RMSE |','|---|---:|---:|---:|']
    for r in overall.itertuples():full.append(f'| {r.arm} | {r.pearson:.6f} | {r.spearman:.6f} | {r.rmse:.6f} |')
    positive=', '.join(contact.loc[contact.ci_lo>0,'group']) or 'none'
    negative=', '.join(contact.loc[contact.ci_hi<0,'group']) or 'none'
    inconclusive=', '.join(contact.loc[(contact.ci_lo<=0)&(contact.ci_hi>=0),'group']) or 'none'
    interpretation=f'Positive pointwise ranking intervals: {positive}; negative intervals: {negative}; intervals containing zero: {inconclusive}. The earlier 1163-case interpretation does not describe this figure. Compare bins using direct contrasts; significance in one bin and not another does not establish a bin difference. CoE and CoDE pretraining recipes differ, and subgroup composition can confound a causal interpretation.'
    manifest=json.loads((MOTIVATION/'figure-manifest.json').read_text())
    links=[f'- [{name}]({name}.png) · [PDF]({name}.pdf) · [SVG]({name}.svg)' for name in manifest['figures'] if any((MOTIVATION/f'{name}.{ext}').exists() for ext in ['png','pdf','svg'])]
    reproduce='Recompute frozen-cohort statistics and redraw:\n\n```bash\ncd figures && python -m _parts.fig_uncertainty.update_filtered\n# Reuse statistics for style-only redraw:\ncd figures && python -m _parts.fig_uncertainty.update_filtered --plots-only\n```\n\nThe manifest selects `frozen_filtered_cl3`; previous plot entry points honor this selection. Only registered and retained figure stems are drawn. Removed layouts are not recreated.'
    distribution='[B-factor ECDF](uncertainty-bfactor-ecdf.png): cumulative distribution of contact-weighted B across all 733 complexes, with 20/30 Å² reference guides. The combined panel overlays the full-cohort ECDF in gray behind the affinity comparison; the standalone 20/30 guides are independent of the current performance bins. [Definition and data](../affinity/metric-review/ranking-by-metric-filtered-cl3/uncertainty-bfactor-ecdf.md).' if 'uncertainty-bfactor-ecdf' in manifest['figures'] and (MOTIVATION/'uncertainty-bfactor-ecdf.png').exists() else ''
    sources='Current affinity statistics and exact memberships: `../affinity/metric-review/ranking-by-metric-filtered-cl3/`. Current decoding tables and source hashes: `../representation/filtered-cl3/`. Original 733-case predictions and OOF files remain intact. Expanded-cohort tables remain in their separate `ranking-by-metric-expanded-cl3` and `representation/expanded-cl3` folders.'
    (MOTIVATION/'README.md').write_text('\n\n'.join(['# Current uncertainty figures: frozen filtered CL3',scope,'\n'.join(links),distribution,bins,'\n'.join(full),historical,reproduce,sources,'[Caption and scope](caption-and-scope.md) · [Contact B factor results](combined-and-rmse.md) · [Metric definitions](metric-definitions.md).'])+'\n')
    caption_draft=f'**Crystallographic disorder and density-support information in learned representations and binding-affinity performance.** Left, out-of-fold Spearman correlations for ridge decoding of contact-weighted B factors, protein-normalized contact B factors, ligand real-space correlation coefficients (RSCC), and protein RSCC from frozen DeepDTA, ProFSA, Nesso-1, CoE, and CoDE representations. All models use the same 732 complete cases from the filtered CL3 test split and identical nested cross-validation folds (five outer folds; three inner folds). Contact B factor weights pocket protein heavy atoms by their inverse-squared distances to ligand heavy atoms; normalization uses the whole-protein mean and standard deviation. Protein RSCC is the report-wide upper median over amino-acid residues. Right, binding-affinity ranking improvement (ΔSpearman, CoDE − CoE), averaged over five probe seeds, for contact B factor {labels} Å² (counts {counts}, respectively). Points are positioned at within-bin median B factors. Error bars show pointwise 95% percentile confidence intervals from 8,000 paired-complex bootstrap resamples, conditional on fixed bins and fitted probes. The gray curve shows the empirical cumulative distribution of contact B factor across all 733 complexes (right axis), including those outside the displayed x range. The exploratory comparison associates higher contact B factor with larger ranking gains; it does not establish a causal contribution of uncertainty. †Nesso-1 carries the manuscript’s affinity-pretraining leakage caveat.'
    (MOTIVATION/'caption-and-scope.md').write_text('\n\n'.join(['# Current caption and interpretation','## Manuscript caption draft',caption_draft,scope,distribution,'**Representation decoding.** '+decoding_scope,'**Affinity comparison.** '+methods,bins,'\n'.join(display_table),interpretation,'**Model provenance.** '+model_scope,'**Historical score comparison.** '+historical,sources])+'\n')
    ylo,yhi=config['combined_right_ylim']
    style=f'Combined source layout: 17.0496 × 4.30 inches, right panel 3.132 inches wide. X ticks show ranges only, without counts. The right y axis spans {ylo:.2f} to {yhi:.2f} with 0.05-spaced ticks. Markers have 8.8-pt diameter, opaque white interiors and blue edges, drawn above the confidence intervals. The thick data line and intervals, original palette, 12.5-pt left bar labels, and absence of a special black zero line are retained.'
    if config.get('combined_distribution_overlay'):
        x_medians=', '.join(f'{v:.6f}' for v in contact.x_median)
        style=f'Combined source layout: 17.4496 × 4.30 inches; right panel remains 3.132 inches wide, with extra outer margin for the secondary y axis. The primary x axis is numeric Contact B factor in Å², displayed from 10 to 40 with ticks 10/20/30/40. Blue points are within-bin median B ({x_medians}), with bin annotations {'shown' if config.get('combined_show_bin_labels',True) else 'omitted'}; these are bin-level statistics, not predictions at individual B values. Gray ECDF steps and shading are behind the performance curve and use all 733 cases. The right axis, tick marks, tick labels, and cumulative-probability title are black; the axis runs from 0 to 1 with ticks 0.1/0.4/0.7/1.0. The x window does not filter or renormalize the distribution: B<10 and B>40 cases remain in its denominator, and the ≥30 affinity bin includes its entire tail. Primary y limits are {ylo:.2f} to {yhi:.2f} with 0.05-spaced ticks. Blue markers have {8.8*config.get('combined_marker_scale',1.):g}-pt diameter, white interiors, 3.68-pt edges; line width is 6.5 pt, vertical CI width is 3.68 pt, and horizontal CI caps are 2.3 pt thick with total x length {config.get('combined_cap_scale',1.):g} Å². No special black zero line is drawn. Left decoding and palette are preserved; bar labels are 12.5 pt and line annotations are 12 pt.'
        if config.get('combined_affinity_display')=='models':
            style=f'Combined source layout: 17.4496 × 4.30 inches, with a 3.132-inch right panel. The primary left y axis shows each model’s mean-over-five-seeds Spearman, not a difference. CoE is pastel green and CoDE is blue. Both curves have their own 8000-paired-complex bootstrap percentile 95% intervals; cutoffs and fitted seeds are fixed. The black primary axis spans {ylo:.2f} to {yhi:.2f} with 0.1-spaced ticks. Numeric Contact B factor spans 10–40 Å² with ticks 10/20/30/40. Both models use identical within-quartile median B positions ({x_medians}); Q1–Q4 mark the groups near the bottom. Hollow markers and the thick curve/interval style are retained. The gray ECDF background is normalized by all 733 complexes, including cases outside the displayed x range. The secondary cumulative-probability axis, ticks and title are black; its ticks are 0.1/0.4/0.7/1.0 on a 0–1 scale. Relative change in the table means 100 × (CoDE Spearman − CoE Spearman) / CoE Spearman, not a percentage-point accuracy gain. Earlier difference and RMSE statistics remain saved and the individual B panels retain their difference estimands.'
        style+=' Left category labels have 3 pt of additional spacing from the x axis; Contact B factor, Normalized contact B factor, Ligand RSCC and Protein RSCC wrap to two lines. The right x-axis title is B factor (Å²), without forcing the left labels to align with it. All visible axis spines and tick marks are 2.64 pt thick (1.2 times the preceding 2.2-pt y axes), including the secondary axis. All numeric y tick labels and right x tick labels are 17.36 pt; left category labels and axis titles remain 19.36 pt. Both primary y-axis titles have 5 pt of additional label padding. The left legend is enlarged another 1.2-fold (1.44 times its original size). The gap between panel axes is 1.9936 inches (1.4 times the previous 1.424 inches), preserving panel widths. Dotted grid lines are 1.2 pt, color #c2c6cd, alpha 1.0. Physical panel dimensions are preserved; the source canvas accommodates larger labels and exports trim outer whitespace. Exports crop outer whitespace with 0.04-inch padding on all four sides, preserving physical panel and font sizes.'
        caption=MOTIVATION/'caption-and-scope.md'
        caption.write_text(caption.read_text()+'\n**Combined distribution overlay.** '+style+'\n')
    style+=' Exports crop outer whitespace to the artwork bounds plus 0.04-inch padding on all four sides; physical panel sizes and font sizes are unchanged.'
    (MOTIVATION/'combined-and-rmse.md').write_text('\n\n'.join(['# Contact B factor: frozen 733-case evaluation',scope,bins,'\n'.join(display_table),'\n'.join(table),interpretation,'\n'.join(full),methods,style,historical,sources])+'\n')
    (MOTIVATION/'expanded-cl3-evaluation.md').write_text('\n\n'.join(['# Cohort selection: original CL3 restored',scope,'Current membership exactly matches frozen `lp_edrscc_v2_cl123` test hash `0795a88e0346f968df11d7abd33f92f2259d277a647f9d175da99d4983305c32`.', 'The earlier exploratory extension included 430 additional cases, for 1163 total, based on available local data and current validation reports. It is inactive in the current figures. The raw split contains 1348 cases; the frozen filtered split contains 733. Historical exclusion criteria must not be reconstructed solely from absent local files or current RSCC values.',sources])+'\n')
    # The metric definitions already document the validated protein-only target and formulas.
    path=MOTIVATION/'metric-definitions.md'
    text=path.read_text().replace('ranking-by-metric-expanded-cl3/','ranking-by-metric-filtered-cl3/')
    path.write_text(text)
